const { execFileSync } = require("child_process");
const g = (...a) => execFileSync("git", a, { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).trim();
let m;
try {
  const antes = g("rev-parse", "HEAD");
  g("pull", "--rebase", "--autostash", "--quiet");
  const ahora = g("rev-parse", "HEAD");
  if (antes === ahora) m = "✓ Proyecto al día con GitHub (no había cambios nuevos).";
  else {
    const l = g("log", "--format=%an: %s", antes + ".." + ahora).split("\n");
    m = "✓ Se trajeron " + l.length + " cambio(s) nuevo(s) de GitHub:\n" + l.slice(0, 5).map((s) => "  · " + s).join("\n") + (l.length > 5 ? "\n  · …" : "");
  }
} catch (e) {
  m = "⚠ No se pudo traer lo último de GitHub. Antes de cambiar nada, pídele a Claude que lo resuelva.\n" + String(e.stderr || e.message).trim().split("\n").slice(0, 3).join("\n");
}
console.log(JSON.stringify({ systemMessage: m, hookSpecificOutput: { hookEventName: "SessionStart", additionalContext: m } }));
